import{_ as r,o,c as t,ag as l}from"./chunks/framework.KxDd3USm.js";const m=JSON.parse('{"title":"软考软件设计师 · 自学总览与进度","description":"","frontmatter":{},"headers":[],"relativePath":"00-总览与进度.md","filePath":"00-总览与进度.md"}'),n={name:"00-总览与进度.md"};function e(i,a,s,h,d,g){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="软考软件设计师-·-自学总览与进度" tabindex="-1">软考软件设计师 · 自学总览与进度 <a class="header-anchor" href="#软考软件设计师-·-自学总览与进度" aria-label="Permalink to &quot;软考软件设计师 · 自学总览与进度&quot;">​</a></h1><blockquote><p>目标：2026 年 10 月 24—27 日考试通过（两科均 ≥45 分）。 本目录是唯一学习资料，不需要看视频。依据《<a href="/ruankao/软件设计师考点大纲.html">../软件设计师考点大纲.md</a>》逐考点展开。 每天怎么安排：先看《<a href="/ruankao/学习计划.html">学习计划.md</a>》（月周日排期 + 背诵轮转 + 复盘体系），本页只记完成进度。</p></blockquote><h2 id="进度-todo-按梯队顺序推进-完成一个勾一个" tabindex="-1">进度 TODO（按梯队顺序推进，完成一个勾一个） <a class="header-anchor" href="#进度-todo-按梯队顺序推进-完成一个勾一个" aria-label="Permalink to &quot;进度 TODO（按梯队顺序推进，完成一个勾一个）&quot;">​</a></h2><h3 id="第一梯队-分值大头-案例直接考-优先学" tabindex="-1">第一梯队（分值大头 + 案例直接考，优先学） <a class="header-anchor" href="#第一梯队-分值大头-案例直接考-优先学" aria-label="Permalink to &quot;第一梯队（分值大头 + 案例直接考，优先学）&quot;">​</a></h3><ul><li>[ ] <strong>01 数据结构与算法</strong>（选择题约 8–10 题 + 案例算法题）→ <a href="/ruankao/01-数据结构与算法/">01-数据结构与算法/00-本课导航.md</a></li><li>[ ] <strong>02 数据库系统</strong>（选择题约 5–6 题 + 案例 SQL/E-R 题）→ <a href="/ruankao/02-数据库系统/">02-数据库系统/00-本课导航.md</a></li><li>[ ] <strong>03 软件工程基础</strong>（选择题约 6–8 题 + 案例数据流图题）→ <a href="/ruankao/03-软件工程基础/">03-软件工程基础/00-本课导航.md</a></li><li>[ ] <strong>04 面向对象与设计模式</strong>（选择题约 5–7 题 + 案例 UML 题）→ <a href="/ruankao/04-面向对象与设计模式/">04-面向对象与设计模式/00-本课导航.md</a></li></ul><h3 id="第二梯队-选择题稳定得分点" tabindex="-1">第二梯队（选择题稳定得分点） <a class="header-anchor" href="#第二梯队-选择题稳定得分点" aria-label="Permalink to &quot;第二梯队（选择题稳定得分点）&quot;">​</a></h3><ul><li>[ ] <strong>05 操作系统</strong>（约 4–6 题）→ <a href="/ruankao/05-操作系统/">05-操作系统/00-本课导航.md</a></li><li>[ ] <strong>06 计算机网络</strong>（约 4–5 题）→ <a href="/ruankao/06-计算机网络/">06-计算机网络/00-本课导航.md</a></li><li>[ ] <strong>07 程序设计语言基础</strong>（约 3–5 题）→ <a href="/ruankao/07-程序设计语言基础/">07-程序设计语言基础/00-本课导航.md</a></li><li>[ ] <strong>08 信息安全</strong>（约 3–4 题）→ <a href="/ruankao/08-信息安全/">08-信息安全/00-本课导航.md</a></li><li>[ ] <strong>09 计算机系统基础</strong>（约 6–8 题）→ <a href="/ruankao/09-计算机系统基础/">09-计算机系统基础/00-本课导航.md</a></li></ul><h3 id="第三梯队-背诵即可拿分" tabindex="-1">第三梯队（背诵即可拿分） <a class="header-anchor" href="#第三梯队-背诵即可拿分" aria-label="Permalink to &quot;第三梯队（背诵即可拿分）&quot;">​</a></h3><ul><li>[ ] <strong>10 标准化与知识产权</strong>（约 3–4 题）→ <a href="/ruankao/10-标准化与知识产权/">10-标准化与知识产权/00-本课导航.md</a></li><li>[ ] <strong>11 专业英语</strong>（固定 5 题）→ <a href="/ruankao/11-专业英语/">11-专业英语/00-本课导航.md</a></li><li>[ ] <strong>12 数学与多媒体</strong>（约 3–4 题）→ <a href="/ruankao/12-数学与多媒体/">12-数学与多媒体/00-本课导航.md</a></li></ul><h3 id="收尾" tabindex="-1">收尾 <a class="header-anchor" href="#收尾" aria-label="Permalink to &quot;收尾&quot;">​</a></h3><ul><li>[ ] <strong>考前全真模拟卷</strong>（75 道选择题 + 5 道案例题）→ <a href="/ruankao/99-考前全真模拟卷/">99-考前全真模拟卷/00-使用方法.md</a></li></ul><h2 id="每课怎么学-固定流程" tabindex="-1">每课怎么学（固定流程） <a class="header-anchor" href="#每课怎么学-固定流程" aria-label="Permalink to &quot;每课怎么学（固定流程）&quot;">​</a></h2><ol><li><strong>读讲义</strong>：从头读到尾，高频考点（标 ★）重点消化。看不懂的地方直接在对话里问我，我换种讲法。</li><li><strong>做课后考题</strong>：合上讲义做，约 15 道选择题 + 1～2 道案例题风格题。</li><li><strong>对答案</strong>：单文件课程翻到末尾的「答案与解析」；分章课程打开独立的「答案与解析」页。错题看解析和易错点，再回讲义补对应知识点。</li><li><strong>做精华题</strong>：5–8 道必考真题风格题，这是考场上最可能原样出现的题型。</li><li><strong>提问/纠偏</strong>：哪块讲得不清楚、哪块想加题，直接告诉我。</li><li><strong>说「下一课」</strong>：我勾掉进度表并生成下一个考点文件。</li></ol><h2 id="学习方法说明" tabindex="-1">学习方法说明 <a class="header-anchor" href="#学习方法说明" aria-label="Permalink to &quot;学习方法说明&quot;">​</a></h2><ul><li><strong>不追求一次读懂</strong>：第一遍读讲义建立框架，题目做错再回来精读对应小节，第二遍才是真正学会。</li><li><strong>计算题动手算</strong>：Cache、磁盘、页式地址、散列表、关键路径等计算题，必须拿笔算，看懂 ≠ 会算。</li><li><strong>表格和口诀优先记</strong>：讲义里的对比表格（如八大排序、内聚耦合七种）是选择题的直接得分工具。</li><li><strong>案例题靠套路</strong>：数据流图、SQL、UML、算法填空四大题各有一套固定解题步骤，讲义里单独成节，按步骤套即可。</li><li><strong>进度紧就砍第三梯队</strong>：时间不够时，10/11/12 三课只背讲义加粗结论，不做题。</li><li><strong>错题进错题本</strong>：练习中做错、蒙对或犹豫的题，记到<a href="/ruankao/interactive/mistake-book/index.html" target="_blank" rel="noopener">错题本与知识图谱</a>（独立看板页），按知识点累计错误次数，考前按薄弱点回炉。</li></ul><h2 id="推进规则-我遵守" tabindex="-1">推进规则（我遵守） <a class="header-anchor" href="#推进规则-我遵守" aria-label="Permalink to &quot;推进规则（我遵守）&quot;">​</a></h2><ul><li>每次只生成一个考点文件，保证深度。</li><li>你指出讲得不清楚的地方，我当场修订该文件。</li><li>12 课完成后生成一份全真模拟卷（75 选择 + 5 大题）收尾。</li></ul>',17)])])}const c=r(n,[["render",e]]);export{m as __pageData,c as default};
